        whatsapp:String(studioSource.whatsapp||'').replace(/\D/g,'').slice(0,15),
        email:studioEmail,
        document:String(studioSource.document||'').replace(/[^0-9A-Za-z./-]/g,'').slice(0,24),
        updatedAt:studioSource.updatedAt||null
