    $('#portalQuickOtpVerify')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector('button[type="submit"]'),code=String(new FormData(form).get('code')||'').trim(),savedEmail=sessionStorage.getItem(`${STUDENT_PORTAL_BACKEND_SESSION_KEY}_otp_email`)||'',email=savedEmail||otpEmail||String($('#portalQuickOwnerEmail')?.value||'').trim();if(!studentPortalValidEmail(email))return toast('Informe primeiro o e-mail e solicite o código.');btn.disabled=true;btn.textContent='Validando…';try{await verifyStudentPortalOwnerOtp(email,code);sessionStorage.removeItem(`${STUDENT_PORTAL_BACKEND_SESSION_KEY}_otp_email`);btn.textContent='Preparando convite…';await finishStudentPortalInviteAfterReauth(studentId)}catch(err){console.error('Portal quick OTP reauth',err);toast(err?.message||'Não foi possível concluir a autenticação.');btn.disabled=false;btn.textContent='Confirmar e continuar'}});
    $('#portalQuickPassword')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),btn=form.querySelector('button[type="submit"]'),email=String($('#portalQuickOwnerEmail')?.value||'').trim();if(!studentPortalValidEmail(email))return toast('Informe um e-mail válido.');btn.disabled=true;btn.textContent='Entrando…';try{await signInStudentPortalOwner(email,fd.get('password'));sessionStorage.removeItem(`${STUDENT_PORTAL_BACKEND_SESSION_KEY}_otp_email`);btn.textContent='Preparando convite…';await finishStudentPortalInviteAfterReauth(studentId)}catch(err){console.error('Portal quick password reauth',err);toast(err?.message||'Não foi possível concluir a autenticação.');btn.disabled=false;btn.textContent='Confirmar com senha'}});
