    if(remote){row.remoteStatus=remote.status==='active'?'active':'revoked';row.activatedAt=remote.activated_at||row.activatedAt;row.inviteEmail=remote.email||row.inviteEmail;}else if(row.remoteStatus==='active'||row.remoteStatus==='revoked')row.remoteStatus=row.lastPublishedAt?'published':'ready';
