    $('#postCreateStudentPortalInvite')?.addEventListener('click',e=>runStudentPortalInviteAction(studentId,{button:e.currentTarget,idleLabel:'Enviar convite agora'}));
    $('#postCreateStudentPortalEmail')?.addEventListener('click',()=>openStudentModal(studentId));
