  // o restante do Canvas e o compartilhamento de arquivos funcionam normalmente.
  async function assessment360ShareRenderCanvas(student,mode='essential'){
    const rows=assessmentsForStudent(student?.id),latest=rows[0],previous=rows[1]||null,first=rows[rows.length-1];
    if(!latest)throw new Error('Avaliação atual indisponível.');
    const W=1080,M=48,CONTENT=W-M*2,MAX_H=3400;
    const BG='#08090b',PANEL='#111318',PANEL2='#15171c',TEXT='#f2efe7',MUTED='#969ba4',GOLD='#d0ad58',GOLD2='#9e7a31',BORDER='#2a2d33',GREEN='#a9c8b4';
    const base=document.createElement('canvas');base.width=W;base.height=MAX_H;const ctx=base.getContext('2d',{alpha:false});if(!ctx)throw new Error('Canvas 2D indisponível.');
    ctx.fillStyle=BG;ctx.fillRect(0,0,W,MAX_H);ctx.textBaseline='top';let y=M;const breaks=[0];
    const font=(size,weight='400')=>{ctx.font=`${weight} ${size}px Arial, sans-serif`;};
    const wrap=(value,maxWidth,size=24,weight='400')=>{font(size,weight);return assessmentReportShareWrap(ctx,String(value||''),maxWidth)};
    const write=(value,x,yy,size=24,weight='400',color=TEXT,maxWidth=null,lineHeight=null)=>{font(size,weight);ctx.fillStyle=color;const lh=lineHeight||Math.round(size*1.34),lines=maxWidth?wrap(value,maxWidth,size,weight):[String(value||'')];for(const line of lines){ctx.fillText(line,x,yy);yy+=lh;}return yy;};
    const box=(x,yy,w,h,fill=PANEL,r=22,stroke=BORDER)=>{ctx.fillStyle=fill;assessmentReportShareRoundRect(ctx,x,yy,w,h,r);ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1.5;ctx.stroke();}};
    const divider=(yy)=>{ctx.strokeStyle='#202329';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(M,yy);ctx.lineTo(W-M,yy);ctx.stroke();};
    const sectionHead=(number,title,subtitle)=>{breaks.push(Math.max(0,y-18));box(M,y,58,58,'#181810',16,'#4a412a');write(number,M+17,y+16,17,'700',GOLD);write(title,M+78,y+4,30,'700',TEXT);if(subtitle)write(subtitle,M+78,y+40,18,'400',MUTED,CONTENT-90,22);y+=82;};
    const metricGrid=(items)=>{const gap=14,cols=2,cw=(CONTENT-gap)/cols,ch=86;items.forEach((item,i)=>{const col=i%2,row=Math.floor(i/2),x=M+col*(cw+gap),yy=y+row*(ch+gap);box(x,yy,cw,ch,PANEL,20,BORDER);write(item[0].toUpperCase(),x+18,yy+16,15,'700','#848993');write(item[1]||'—',x+18,yy+43,25,'700',TEXT,cw-36,28);});y+=Math.ceil(items.length/2)*(ch+gap)-gap;};
    const deltaGrid=(data)=>{const lines=data.lines||[],gap=14,cw=(CONTENT-gap)/2,ch=78;lines.forEach((line,i)=>{const clean=String(line).replace(/^•\s*/,'');const idx=clean.indexOf(': '),label=idx>=0?clean.slice(0,idx):'Indicador',value=idx>=0?clean.slice(idx+2):clean;const col=i%2,row=Math.floor(i/2),x=M+col*(cw+gap),yy=y+row*(ch+gap);box(x,yy,cw,ch,PANEL,20,BORDER);write(label.toUpperCase(),x+18,yy+16,14,'700','#848993');write(value,x+18,yy+41,22,'700',GOLD,cw-36,25);});if(lines.length)y+=Math.ceil(lines.length/2)*(ch+gap)-gap;else{box(M,y,CONTENT,72,PANEL,18,BORDER);write('Sem indicadores comuns suficientes para comparação.',M+18,y+22,20,'400',MUTED,CONTENT-36);y+=72;}if(data.composition?.showGuard){y+=14;box(M,y,CONTENT,88,'#12130f',18,'#3b3928');write('COMPOSIÇÃO PROTEGIDA',M+18,y+16,15,'700',GOLD);write(`${data.composition.reason}.`,M+18,y+43,18,'400',MUTED,CONTENT-36,23);y+=88;}};
    const chip=(text,x,yy,w)=>{box(x,yy,w,42,'#17191d',18,'#31343a');write(text,x+14,yy+11,16,'700','#d6d2c7',w-28,19)};

    // Cabeçalho premium
    box(M,y,CONTENT,184,'#14161a',28,'#393329');
    write(brandStudioName().toUpperCase(),M+28,y+28,17,'700',GOLD);write('Resumo Evolução 360°',M+28,y+58,40,'700',TEXT);
    write(mode==='complete'?'VERSÃO COMPLETA':'VERSÃO ESSENCIAL',M+28,y+116,15,'700',MUTED);
    box(W-M-112,y+34,76,76,'#caa84f',22,null);write(brandInitials(),W-M-91,y+56,26,'800','#17140d');y+=204;

    // Identificação
    box(M,y,CONTENT,146,PANEL2,24,BORDER);write('ALUNO',M+22,y+18,14,'700',MUTED);write(student.name,M+22,y+45,31,'700',TEXT,CONTENT*0.58,36);
    write('AVALIAÇÃO ATUAL',M+22,y+96,14,'700',MUTED);write(`${fmtDate(latest.date)} • ${rows.length} ${rows.length===1?'registro':'registros'}`,M+172,y+94,18,'700','#d4d0c6',CONTENT*0.48,22);
    const shareRef=bodyCompositionReferenceResult(latest,student),protocol=shareRef.complete?bodyCompositionReferenceCaption(latest,student):'Sem composição completa';write('REFERÊNCIA',M+CONTENT*0.64,y+18,14,'700',MUTED);write(protocol,M+CONTENT*0.64,y+45,18,'700','#d4d0c6',CONTENT*0.33,23);y+=164;
    const objective=assessmentOptionLabel(ASSESSMENT_OBJECTIVES,latest.objective)||'Não definido',stage=assessmentOptionLabel(ASSESSMENT_STAGES,latest.stage)||'Não definido';
    const chipGap=12,chipW=(CONTENT-chipGap)/2;chip(`OBJETIVO • ${objective}`,M,y,chipW);chip(`ESTÁGIO • ${stage}`,M+chipW+chipGap,y,chipW);y+=66;

    // Visão atual
    sectionHead('01','Visão atual','Indicadores do registro mais recente');
    const comp=bodyCompositionReferenceResult(latest,student);const current=[
      ['Peso',assessment360ShareValid(latest?.weight)?`${assessmentNumber(latest.weight,1)} kg`:'—'],
      ['IMC',assessment360ShareValid(assessmentBMI(latest))?assessmentNumber(assessmentBMI(latest),1):'—'],
      ['IRCQ',assessment360ShareValid(assessmentIRCQ(latest))?assessmentNumber(assessmentIRCQ(latest),2):'—'],
      ['Cintura',assessment360ShareValid(latest?.measurements?.waist)?`${assessmentNumber(latest.measurements.waist,1)} cm`:'—'],
      ['Abdômen',assessment360ShareValid(latest?.measurements?.abdomen)?`${assessmentNumber(latest.measurements.abdomen,1)} cm`:'—'],
      ['Quadril',assessment360ShareValid(latest?.measurements?.hip)?`${assessmentNumber(latest.measurements.hip,1)} cm`:'—'],
      [comp.complete?(comp.source==='external'?'Gordura medida':'Gordura estimada'):'Gordura corporal',comp.complete?`${assessmentNumber(comp.bodyFatPercent,1)}%`:'—']
    ];metricGrid(current);y+=26;

    // Última x anterior
    sectionHead('02',previous?'Última × anterior':'Linha de base',previous?`Base ${fmtDate(previous.date)}`:'Comparação liberada na 2ª avaliação');
    if(previous)deltaGrid(assessment360ShareComparisonLines(latest,previous,student,{longitudinal:false}));else{box(M,y,CONTENT,72,PANEL,18,BORDER);write('O primeiro registro já está preservado como linha de base.',M+18,y+22,20,'400',MUTED,CONTENT-36);y+=72;}y+=26;

    if(mode==='complete'&&rows.length>2){sectionHead('03','Primeira × atual',`Trajetória desde ${fmtDate(first.date)}`);deltaGrid(assessment360ShareComparisonLines(latest,first,student,{longitudinal:true}));y+=26;}
    if(mode==='complete'){
      const bilateral=assessment360ShareBilateralRows(latest),number=rows.length>2?'04':'03';sectionHead(number,'Comparativo bilateral atual','Direito × esquerdo no registro mais recente');
      if(bilateral.length){const gap=14,cw=(CONTENT-gap)/2,ch=102;bilateral.forEach((b,i)=>{const col=i%2,row=Math.floor(i/2),x=M+col*(cw+gap),yy=y+row*(ch+gap);box(x,yy,cw,ch,PANEL,20,BORDER);write(b.label.toUpperCase(),x+18,yy+14,14,'700','#848993');write(`D ${assessmentNumber(b.r,1)} cm • E ${assessmentNumber(b.l,1)} cm`,x+18,yy+39,21,'700',TEXT,cw-36,25);write(b.diff<.05?'Equivalentes no registro':`Diferença ${assessmentNumber(b.diff,1)} cm • ${b.side}`,x+18,yy+70,16,'700',GOLD,cw-36,20);});y+=Math.ceil(bilateral.length/2)*(ch+gap)-gap;}else{box(M,y,CONTENT,72,PANEL,18,BORDER);write('Sem pares bilaterais completos neste registro.',M+18,y+22,20,'400',MUTED,CONTENT-36);y+=72;}y+=26;
    }

    // Rodapé metodológico
    breaks.push(Math.max(0,y-18));box(M,y,CONTENT,128,'#0f1513',22,'#26352f');write('LEITURA PROFISSIONAL',M+22,y+18,15,'700',GREEN);write('Direções numéricas não representam, isoladamente, melhora ou piora. Comparações de composição respeitam compatibilidade metodológica.',M+22,y+48,18,'400','#a4aca7',CONTENT-44,25);y+=148;divider(y);write(`MB Gestor Luxury Pro V${APP_VERSION} • Resumo Evolução 360°`,M,y+18,14,'700','#7f7560');y+=54;

    const finalH=Math.max(480,Math.ceil(y+M));if(finalH>MAX_H)throw new Error('Resumo visual excedeu o limite seguro.');
    const out=document.createElement('canvas');out.width=W;out.height=finalH;const outCtx=out.getContext('2d',{alpha:false});if(!outCtx)throw new Error('Canvas final indisponível.');outCtx.fillStyle=BG;outCtx.fillRect(0,0,W,finalH);outCtx.drawImage(base,0,0,W,finalH,0,0,W,finalH);out._mbPageBreaks=breaks.filter(v=>v>0&&v<finalH);return out;
  }
  async function assessment360ShareImageFile(student,mode){
    const latest=assessmentsForStudent(student.id)[0],canvas=await assessment360ShareRenderCanvas(student,mode),blob=await assessment360ShareCanvasBlob(canvas,'image/png');return new File([blob],`${assessment360ShareFileBase(student,latest,mode)}.png`,{type:'image/png',lastModified:Date.now()});
  }
  async function assessment360SharePdfFile(student,mode){
    const latest=assessmentsForStudent(student.id)[0],source=await assessment360ShareRenderCanvas(student,mode),ratio=841.89/595.28,maxH=Math.max(1,Math.floor(source.width*ratio)),breaks=[0,...(source._mbPageBreaks||[]),source.height].sort((a,b)=>a-b),ranges=[];let start=0;
    while(start<source.height){const limit=Math.min(source.height,start+maxH);let end=breaks.filter(v=>v>start+180&&v<=limit).pop()||limit;if(end<=start)end=limit;ranges.push([start,end]);start=end;}
    const images=[];for(const [from,to] of ranges){const h=Math.max(1,to-from),page=document.createElement('canvas');page.width=source.width;page.height=maxH;const ctx=page.getContext('2d',{alpha:false});if(!ctx)throw new Error('Canvas do PDF indisponível.');ctx.fillStyle='#08090b';ctx.fillRect(0,0,page.width,page.height);ctx.drawImage(source,0,from,source.width,h,0,0,source.width,h);images.push({bytes:await assessmentReportShareCanvasJPEGDirect(page,.92),width:page.width,height:page.height});}
    const blob=assessmentReportBuildImagePDF(images);return new File([blob],`${assessment360ShareFileBase(student,latest,mode)}.pdf`,{type:'application/pdf',lastModified:Date.now()});
  }
  async function assessment360ShareNativeFile(file,student,kind){
    const data={files:[file],title:`Evolução 360° • ${student.name}`};
    if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){
      try{await navigator.share(data);toast(`${kind} enviado ao compartilhamento do aparelho.`);return true}
      catch(error){if(error?.name==='AbortError'){toast('Compartilhamento cancelado.');return false}console.warn('Compartilhamento nativo indisponível; salvando arquivo.',error)}
    }
    assessmentReportDownloadShareFile(file);toast(`${kind} gerado e salvo no aparelho.`);return true;
  }
  function openAssessment360Share(studentId,returnTo='panel'){
    const student=state.students.find(s=>String(s.id)===String(studentId));if(!student)return;const rows=assessmentsForStudent(studentId);if(!rows.length)return toast('Registre a primeira avaliação antes de compartilhar a evolução.');
    let mode='essential';const phoneCheck=validateWhatsApp(student.whatsapp);
    const renderShare=()=>{const preview=$('#assessment360SharePreview');if(preview)preview.innerHTML=assessment360SharePreviewHTML(student,mode);$$('[data-assessment-share-mode]',modalRoot).forEach(b=>b.classList.toggle('active',b.dataset.assessmentShareMode===mode));};
    openModal(`Compartilhar evolução • ${student.name}`,`<div class="assessment-share-intro"><div><span class="section-overline">EVOLUÇÃO 360° • RESUMO PREMIUM</span><strong>Resumo visual pronto para compartilhar</strong><p>Escolha Essencial ou Completo e envie como imagem ou PDF. O texto do WhatsApp fica apenas como alternativa.</p></div><span>${icon('share')}</span></div><div class="assessment-share-mode"><button type="button" class="active" data-assessment-share-mode="essential">Essencial</button><button type="button" data-assessment-share-mode="complete">Completo</button></div><div id="assessment360SharePreview"></div><div class="assessment-share-output-note"><strong>Compartilhamento visual</strong><span>A imagem e o PDF reproduzem este resumo e mantêm as proteções metodológicas do Painel 360°.</span></div><div class="assessment-share-primary-actions"><button type="button" class="btn btn-primary" id="assessment360ShareImage">${icon('share')} <span>Compartilhar imagem</span></button><button type="button" class="btn btn-secondary" id="assessment360SharePdf">${icon('file')} <span>PDF Premium</span></button></div><div class="assessment-share-secondary-actions"><button type="button" class="btn btn-secondary assessment-share-text-action" id="assessment360ShareCopy">${icon('file')} Copiar resumo</button><button type="button" class="btn btn-secondary assessment-share-text-action" id="assessment360ShareWhatsapp" ${phoneCheck.valid?'':'disabled'}>${icon('message')} WhatsApp em texto</button><button type="button" class="btn btn-secondary" id="assessment360ShareBack">${returnTo==='profile'?'Voltar à ficha':'Voltar ao Painel 360°'}</button></div>${phoneCheck.valid?'':`<div class="assessment-share-phone-warning"><strong>WhatsApp em texto indisponível</strong><span>${escapeHTML(phoneCheck.reason)} Você ainda pode usar Copiar resumo, compartilhar imagem ou gerar o PDF.</span></div>`}`);
    $$('[data-assessment-share-mode]',modalRoot).forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.assessmentShareMode||'essential';renderShare()}));
    $('#assessment360ShareBack')?.addEventListener('click',()=>{if(returnTo==='profile')openStudentHistory(studentId);else openAssessment360Panel(studentId)});
    $('#assessment360ShareImage')?.addEventListener('click',async e=>{const btn=e.currentTarget,span=btn.querySelector('span'),label=span?.textContent||'Compartilhar imagem';btn.disabled=true;if(span)span.textContent='Preparando imagem…';try{const file=await assessment360ShareImageFile(student,mode);await assessment360ShareNativeFile(file,student,'Imagem Premium')}catch(error){console.error('Resumo 360 imagem',error);toast('Não foi possível gerar a imagem neste aparelho.')}finally{btn.disabled=false;if(span)span.textContent=label}});
    $('#assessment360SharePdf')?.addEventListener('click',async e=>{const btn=e.currentTarget,span=btn.querySelector('span'),label=span?.textContent||'PDF Premium';btn.disabled=true;if(span)span.textContent='Preparando PDF…';try{const file=await assessment360SharePdfFile(student,mode);await assessment360ShareNativeFile(file,student,'PDF Premium')}catch(error){console.error('Resumo 360 PDF',error);toast('Não foi possível gerar o PDF neste aparelho.')}finally{btn.disabled=false;if(span)span.textContent=label}});
    $('#assessment360ShareCopy')?.addEventListener('click',()=>copyText(assessment360ShareText(student,mode)));
    $('#assessment360ShareWhatsapp')?.addEventListener('click',()=>{if(!phoneCheck.valid)return toast(phoneCheck.reason);const text=assessment360ShareText(student,mode);window.open(`https://wa.me/${phoneCheck.international}?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer');toast('WhatsApp aberto com a versão em texto.');});
    renderShare();
  }

  function openAssessment360Panel(studentId){
    const student=state.students.find(s=>String(s.id)===String(studentId));if(!student)return;
    const rowsDesc=assessmentsForStudent(studentId);
    if(!rowsDesc.length){
      openModal(`Evolução 360° • ${student.name}`,`<div class="assessment-chart-empty"><strong>Primeira avaliação ainda não registrada</strong><span>O Painel 360° é liberado automaticamente após o primeiro registro físico.</span></div><div class="modal-actions"><button class="btn btn-secondary" id="assessment360BackProfile">Voltar à ficha</button><button class="btn btn-primary" id="assessment360CreateFirst">${icon('plus')} Criar avaliação</button></div>`);
      $('#assessment360BackProfile')?.addEventListener('click',()=>openStudentHistory(studentId));
      $('#assessment360CreateFirst')?.addEventListener('click',()=>openAssessmentModal(studentId));
      return;
    }
    const latest=rowsDesc[0],previous=rowsDesc[1]||null,first=rowsDesc[rowsDesc.length-1],comp=bodyCompositionReferenceResult(latest,student),bilateral=assessment360BilateralHTML(latest);
    const protocol=comp.complete?bodyCompositionReferenceCaption(latest,student):'Sem composição completa';
    const previousGuard=previous&&comp.complete&&bodyCompositionReferenceResult(previous,student).complete&&!bodyCompositionReferenceCompatible(latest,previous,student,{longitudinal:false})?`<div class="body-comp-evolution-guard assessment-360-guard"><strong>Composição protegida na comparação anterior</strong><span>${escapeHTML(bodyCompositionReferenceCompatibilityReason(latest,previous,student,{longitudinal:false}))}. Peso e perímetros continuam comparáveis, mas o Painel 360° não mistura resultados metodologicamente incompatíveis.</span></div>`:'';
    const firstGuard=rowsDesc.length>1&&comp.complete&&bodyCompositionReferenceResult(first,student).complete&&!bodyCompositionReferenceCompatible(latest,first,student,{longitudinal:true})?`<div class="body-comp-evolution-guard assessment-360-guard"><strong>Composição protegida na comparação longitudinal</strong><span>${escapeHTML(bodyCompositionReferenceCompatibilityReason(latest,first,student,{longitudinal:true}))}; a composição corporal permanece fora dessa comparação.</span></div>`:'';
    openModal(`Evolução 360° • ${student.name}`,`<section class="assessment-360-hero"><div><span class="section-overline">PAINEL DE EVOLUÇÃO 360°</span><h3>${escapeHTML(student.name)}</h3><p>${rowsDesc.length} ${rowsDesc.length===1?'avaliação registrada':'avaliações registradas'} • ${fmtDate(first.date)} → ${fmtDate(latest.date)}</p></div><div class="assessment-360-count"><strong>${rowsDesc.length}</strong><span>registros</span></div></section>
      <div class="assessment-360-meta"><span><b>Última avaliação</b>${fmtDate(latest.date)}</span><span><b>Protocolo atual</b>${escapeHTML(protocol)}</span>${comp.complete?`<span><b>Composição atual</b>${assessmentNumber(comp.bodyFatPercent,1)}% • ${comp.source==='external'?'medido externamente':'estimado'}</span>`:''}</div>
      ${assessmentContextChips(latest)}
      <div class="section-head compact-head assessment-360-section-head"><div><h3>Visão atual</h3><p>Indicadores disponíveis no registro mais recente.</p></div></div>
      ${assessment360CurrentMetrics(student,latest)}
      ${previous?`<div class="section-head compact-head assessment-360-section-head"><div><h3>Última × anterior</h3><p>Variação numérica em relação a ${fmtDate(previous.date)}.</p></div></div>${assessment360ComparisonStrip(latest,previous,student,'Desde a avaliação anterior')}${previousGuard}`:`<div class="assessment-360-empty"><strong>Comparação anterior será liberada na 2ª avaliação</strong><span>O primeiro registro já está preservado como linha de base.</span></div>`}
      ${rowsDesc.length>1?`<div class="section-head compact-head assessment-360-section-head"><div><h3>Primeira × atual</h3><p>Trajetória acumulada desde ${fmtDate(first.date)}.</p></div></div>${assessment360ComparisonStrip(latest,first,student,'Desde o primeiro registro')}${firstGuard}`:''}
      <div class="section-head compact-head assessment-360-section-head"><div><h3>Comparativo bilateral atual</h3><p>Direito × esquerdo no registro mais recente, sem classificação automática.</p></div></div>${bilateral?`<div class="assessment-bilateral-cards assessment-360-bilateral">${bilateral}</div>`:`<div class="assessment-360-empty compact"><strong>Sem pares bilaterais completos</strong><span>Quando houver medidas D/E completas, elas aparecerão aqui automaticamente.</span></div>`}
      <div class="assessment-360-method-note"><strong>Leitura profissional</strong><span>Setas e diferenças representam apenas direção numérica. O Painel 360° não classifica aumento ou redução como positivo ou negativo e protege comparações de composição entre origens, métodos, equipamentos ou protocolos incompatíveis.</span></div>
      <div class="assessment-360-actions"><button class="btn btn-primary btn-small" id="assessment360New">${icon('plus')} Nova avaliação</button><button class="btn btn-secondary btn-small assessment-360-share-action" id="assessment360Share">${icon('share')} Compartilhar evolução</button><button class="btn btn-secondary btn-small" id="assessment360Report">${icon('file')} Relatório Premium</button><button class="btn btn-secondary btn-small" id="assessment360History">Histórico</button>${rowsDesc.length>1?`<button class="btn btn-secondary btn-small" id="assessment360Charts">${icon('chart')} Gráficos detalhados</button>`:''}<button class="btn btn-secondary btn-small" id="assessment360BackProfile">Voltar à ficha</button></div>`);
    $('#assessment360New')?.addEventListener('click',()=>openAssessmentModal(studentId));
    $('#assessment360Share')?.addEventListener('click',()=>openAssessment360Share(studentId,'panel'));
    $('#assessment360Report')?.addEventListener('click',()=>openAssessmentReport(studentId,latest.id));
    $('#assessment360History')?.addEventListener('click',()=>openAssessmentHistory(studentId));
    $('#assessment360Charts')?.addEventListener('click',()=>openAssessmentEvolution(studentId));
    $('#assessment360BackProfile')?.addEventListener('click',()=>openStudentHistory(studentId));
  }
  function assessmentProfileCardHTML(student){
    const rows=assessmentsForStudent(student.id),a=rows[0];
    if(!a)return `<section class="profile-assessment-card empty-assessment"><div class="profile-assessment-head"><div><span class="section-overline">AVALIAÇÃO FÍSICA</span><strong>Ainda sem avaliação</strong><p>Opcional. O cadastro e todas as demais funções continuam normalmente.</p></div><span class="assessment-emblem">${icon('chart')}</span></div><button class="btn btn-secondary btn-small" id="historyAssessmentNew">${icon('plus')} Criar primeira avaliação</button></section>`;
    const bmi=assessmentBMI(a),ircq=assessmentIRCQ(a),bc=bmiClassification(a,student),rc=ircqClassification(a,student),comp=bodyCompositionReferenceResult(a,student),previous=rows[1]||null,first=rows[rows.length-1];
    const previousProtected=Boolean(previous&&comp.complete&&bodyCompositionReferenceResult(previous,student).complete&&!bodyCompositionReferenceCompatible(a,previous,student,{longitudinal:false}));
    const firstProtected=Boolean(rows.length>1&&String(first.id)!==String(previous?.id)&&comp.complete&&bodyCompositionReferenceResult(first,student).complete&&!bodyCompositionReferenceCompatible(a,first,student,{longitudinal:true}));
    const protectedNote=label=>`<div class="profile-assessment-guard-pill"><span>◈</span><strong>Composição protegida</strong><small>${escapeHTML(label)}</small></div>`;
    return `<section class="profile-assessment-card profile-assessment-360"><div class="profile-assessment-head"><div><span class="section-overline">EVOLUÇÃO 360°</span><strong>Última avaliação • ${fmtDate(a.date)}</strong><p>${rows.length} ${rows.length===1?'registro':'registros'} • acompanhamento físico centralizado.</p></div><span class="assessment-emblem">${icon('chart')}</span></div>${assessmentContextChips(a)}<div class="assessment-profile-metrics">${assessmentMetric(bmi==null?'—':assessmentNumber(bmi,1),'IMC',bc.label,bc.tone)}${assessmentMetric(ircq==null?'—':assessmentNumber(ircq,2),'IRCQ',rc.label,rc.tone)}${comp.complete?assessmentMetric(`${assessmentNumber(comp.bodyFatPercent,1)}%`,comp.source==='external'?'Gordura medida':'Gordura estimada',comp.methodLabel):assessmentMetric(a.weight?`${assessmentNumber(a.weight,1)} kg`:'—','Peso')}${assessmentMetric(a.measurements?.waist?`${assessmentNumber(a.measurements.waist,1)} cm`:'—','Cintura')}</div>${previous?assessment360ComparisonStrip(a,previous,student,'Última × anterior'):''}${previousProtected?protectedNote(bodyCompositionReferenceCompatibilityReason(a,previous,student,{longitudinal:false})):''}${rows.length>1&&String(first.id)!==String(previous?.id)?assessment360ComparisonStrip(a,first,student,'Primeira × atual'):''}${firstProtected?protectedNote(bodyCompositionReferenceCompatibilityReason(a,first,student,{longitudinal:true})):''}<div class="profile-assessment-actions profile-assessment-360-actions"><button class="btn btn-primary btn-small" id="historyAssessment360">${icon('chart')} Painel 360°</button><button class="btn btn-secondary btn-small assessment-360-share-action" id="historyAssessmentShare">${icon('share')} Compartilhar evolução</button><button class="btn btn-secondary btn-small" id="historyAssessmentNew">${icon('plus')} Nova avaliação</button><button class="btn btn-secondary btn-small" id="historyAssessmentReport">${icon('file')} Relatório</button><button class="btn btn-secondary btn-small" id="historyAssessmentHistory">Histórico</button>${rows.length>1?`<button class="btn btn-secondary btn-small" id="historyAssessmentEvolution">${icon('chart')} Gráficos</button>`:''}</div></section>`;
  }
  function renderAssessments(){
    const students=[...state.students].sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'pt-BR'));
    const withAssessment=students.filter(s=>latestAssessment(s.id)).length,total=(state.physicalAssessments||[]).filter(a=>students.some(s=>String(s.id)===String(a.studentId))).length,withEvolution=students.filter(s=>assessmentsForStudent(s.id).length>1).length,reviewList=reassessmentAttentionStudents(90),reviewIds=new Set(reviewList.map(x=>String(x.s.id)));
    viewEl.innerHTML=`<section class="assessment-hero"><div><span class="section-overline">AVALIAÇÃO FÍSICA</span><h2>Avaliação integrada</h2><p>Antropometria, composição corporal, postura e evolução em um só fluxo — com histórico comparável e acompanhamento profissional.</p></div><span class="assessment-hero-icon">${icon('chart')}</span></section>
      <div class="assessment-feature-grid">
        <button type="button" class="assessment-guide-entry" id="assessmentGuideEntry"><span class="assessment-guide-entry-icon">${icon('body')}</span><span><b>Guia anatômico premium</b><small>Consulte os pontos de mensuração antes ou durante a avaliação.</small></span><i>${icon('eye')}</i></button>
        <button type="button" class="assessment-guide-entry assessment-composition-entry" id="assessmentCompositionEntry"><span class="assessment-guide-entry-icon">${icon('chart')}</span><span><b>Composição corporal</b><small>% de gordura, massa gorda e massa livre com origem e método rastreáveis.</small></span><i class="assessment-entry-arrow">›</i></button>
        <button type="button" class="assessment-guide-entry assessment-postural-entry" id="assessmentPosturalEntry"><span class="assessment-guide-entry-icon">${icon('body')}</span><span><b>Avaliação Postural Premium</b><small>Quatro vistas, achados estruturados, histórico e evolução postural.</small></span><i class="assessment-entry-arrow">›</i></button>
        <button type="button" class="assessment-guide-entry assessment-evolution-entry" id="assessmentEvolutionEntry"><span class="assessment-guide-entry-icon">${icon('chart')}</span><span><b>Evolução 360°</b><small>Comparativos, gráficos, relatórios e compartilhamento da evolução.</small></span><i class="assessment-entry-arrow">›</i></button>
      </div>
      <section class="metrics assessment-top-metrics">${metricCard('users',students.length,'Alunos cadastrados')}${metricCard('check',withAssessment,'Com avaliação','good')}${metricCard('chart',total,'Avaliações salvas')}${metricCard('chart',withEvolution,'Com evolução')}</section>
      <div class="assessment-guidance"><strong>Base antropométrica responsável</strong><span>IMC = peso ÷ altura² • IRCQ = cintura ÷ quadril. A composição corporal preserva a origem do resultado — estimado pelo MB Gestor ou medido externamente — sem classificação estética automática.</span></div>
      <div class="assessment-composition-mode-banner hidden" id="assessmentCompositionModeBanner" aria-live="polite"><div><strong>Composição corporal</strong><small>Selecione um aluno para iniciar ou continuar. Se já houver avaliação hoje, o app retoma o registro para evitar duplicidade.</small></div><button type="button" id="assessmentCompositionModeExit">Voltar às avaliações</button></div>
      <div class="section-head" id="assessmentStudentsSection"><div><h3 id="assessmentStudentsTitle">Alunos</h3><p id="assessmentStudentsHint">Selecione um aluno para avaliar, consultar histórico ou acompanhar evolução.</p></div></div>
      <div class="search-wrap">${icon('search')}<input id="assessmentSearch" placeholder="Buscar aluno por nome" autocomplete="off" /></div>
      <div class="tabs assessment-tabs"><button class="tab ${assessmentFilter==='all'?'active':''}" data-assessment-filter="all">Todos</button><button class="tab ${assessmentFilter==='done'?'active':''}" data-assessment-filter="done">Avaliados</button><button class="tab ${assessmentFilter==='evolution'?'active':''}" data-assessment-filter="evolution">Com evolução</button><button class="tab ${assessmentFilter==='review'?'active':''}" data-assessment-filter="review">Reavaliar 90+ (${reviewList.length})</button><button class="tab ${assessmentFilter==='pending'?'active':''}" data-assessment-filter="pending">Sem avaliação</button></div>
      <section id="assessmentStudentList" class="cards assessment-student-list"></section>`;
    let compositionMode=false;
    const setCompositionMode=active=>{compositionMode=Boolean(active);$('#assessmentCompositionModeBanner')?.classList.toggle('hidden',!compositionMode);const section=$('#assessmentStudentsSection'),title=$('#assessmentStudentsTitle'),hint=$('#assessmentStudentsHint');section?.classList.toggle('is-composition-target',compositionMode);if(title)title.textContent=compositionMode?'Escolha o aluno':'Alunos';if(hint)hint.textContent=compositionMode?'Selecione um aluno abaixo para iniciar ou continuar a composição corporal.':'Selecione um aluno para avaliar, consultar histórico ou acompanhar evolução.';draw();if(compositionMode){toast('Composição corporal: escolha um aluno para continuar.');setTimeout(()=>document.getElementById('assessmentCompositionModeBanner')?.scrollIntoView({behavior:'smooth',block:'start'}),80)}};
    const draw=()=>{const q=String($('#assessmentSearch')?.value||'').trim().toLocaleLowerCase('pt-BR');const list=students.filter(s=>{const rows=assessmentsForStudent(s.id),has=Boolean(rows.length);if(assessmentFilter==='done'&&!has)return false;if(assessmentFilter==='evolution'&&rows.length<2)return false;if(assessmentFilter==='review'&&!reviewIds.has(String(s.id)))return false;if(assessmentFilter==='pending'&&has)return false;return !q||String(s.name||'').toLocaleLowerCase('pt-BR').includes(q)});$('#assessmentStudentList').innerHTML=list.length?list.map(s=>{const rows=assessmentsForStudent(s.id),a=rows[0],todayAssessment=rows.find(r=>String(r.date)===isoToday())||null,bmi=a?assessmentBMI(a):null,ircq=a?assessmentIRCQ(a):null,bc=a?bmiClassification(a,s):null,rc=a?ircqClassification(a,s):null,comp=a?bodyCompositionReferenceResult(a,s):null,compositionAction=compositionMode?(todayAssessment?'Continuar composição':a?'Nova composição':'Iniciar composição'):(a?'Nova':'Avaliar');return `<article class="card assessment-student-card ${compositionMode?'is-composition-mode':''}"><div class="assessment-student-main"><div class="student-photo tiny-photo">${s.photoData?`<img src="${s.photoData}" alt="" />`:`<span>${escapeHTML((s.name||'?').charAt(0).toUpperCase())}</span>`}</div><div><strong>${escapeHTML(s.name)}</strong><span>${a?`Última avaliação: ${fmtDate(a.date)} • ${rows.length} ${rows.length===1?'registro':'registros'}`:'Nenhuma avaliação registrada'}${s.active===false?' • aluno inativo':''}</span>${a?`${assessmentContextChips(a)}<div class="assessment-inline-status"><span>IMC <b>${bmi==null?'—':assessmentNumber(bmi,1)}</b> ${assessmentStatusPill(bc)}</span><span>IRCQ <b>${ircq==null?'—':assessmentNumber(ircq,2)}</b> ${assessmentStatusPill(rc)}</span>${comp?.complete?`<span class="assessment-composition-inline">Gordura <b>${assessmentNumber(comp.bodyFatPercent,1)}%</b><i>${escapeHTML(comp.methodLabel)} • ${comp.source==='external'?'externa':'MB'}</i></span>`:''}</div>`:''}</div></div><div class="assessment-student-actions"><button class="btn ${compositionMode||!a?'btn-primary':'btn-secondary'} btn-small js-assessment-new" data-id="${s.id}" data-today-assessment="${todayAssessment?.id||''}">${icon('plus')} ${compositionAction}</button>${a?`<button class="btn btn-secondary btn-small js-assessment-history" data-id="${s.id}">Histórico</button>`:''}${rows.length>1&&!compositionMode?`<button class="btn btn-secondary btn-small js-assessment-evolution" data-id="${s.id}">${icon('chart')} Evolução</button>`:''}</div></article>`}).join(''):emptyState('Nenhum aluno neste filtro','Ajuste a busca ou escolha outro filtro.');$$('.js-assessment-new',viewEl).forEach(b=>b.addEventListener('click',()=>{if(compositionMode){openAssessmentModal(b.dataset.id,b.dataset.todayAssessment||null,{focusComposition:true});return;}openAssessmentModal(b.dataset.id)}));$$('.js-assessment-history',viewEl).forEach(b=>b.addEventListener('click',()=>openAssessmentHistory(b.dataset.id)));$$('.js-assessment-evolution',viewEl).forEach(b=>b.addEventListener('click',()=>openAssessmentEvolution(b.dataset.id)));};
    $('#assessmentGuideEntry')?.addEventListener('click',()=>{if(readAssessmentGuideMode()==='skinfold'){openSkinfoldGuide();return}openAnatomicalGuide()});
    $('#assessmentCompositionEntry')?.addEventListener('click',()=>setCompositionMode(true));
    $('#assessmentPosturalEntry')?.addEventListener('click',renderPosturalAssessments);
    $('#assessmentEvolutionEntry')?.addEventListener('click',()=>{setCompositionMode(false);assessmentFilter='evolution';$$('[data-assessment-filter]',viewEl).forEach(x=>x.classList.toggle('active',x.dataset.assessmentFilter==='evolution'));draw();toast('Evolução 360°: escolha um aluno e toque em Evolução.');setTimeout(()=>document.getElementById('assessmentStudentsSection')?.scrollIntoView({behavior:'smooth',block:'start'}),80)});
    $('#assessmentCompositionModeExit')?.addEventListener('click',()=>setCompositionMode(false));
    $('#assessmentSearch')?.addEventListener('input',draw);$$('[data-assessment-filter]',viewEl).forEach(b=>b.addEventListener('click',()=>{assessmentFilter=b.dataset.assessmentFilter;$$('[data-assessment-filter]',viewEl).forEach(x=>x.classList.toggle('active',x===b));draw()}));draw();
  }

