    const layer=document.createElement('div');layer.className='body-comp-picker-layer';layer.innerHTML=`<div class="body-comp-picker-shell" role="dialog" aria-modal="true" aria-label="Escolher protocolo de composição corporal"><div class="body-comp-picker-head"><div><span>COMPOSIÇÃO CORPORAL</span><strong>Escolher protocolo</strong><small>O método escolhido fica registrado junto da avaliação.</small></div><button type="button" data-body-comp-close aria-label="Fechar">${icon('x')}</button></div><div class="body-comp-picker-content"><div class="body-comp-picker-group"><span>SEM ESTIMATIVA</span>${bodyCompositionPickerCard(BODY_COMPOSITION_METHODS[0],current)}</div><div class="body-comp-picker-group"><span>PERÍMETROS</span>${perimeter.map(m=>bodyCompositionPickerCard(m,current)).join('')}</div><div class="body-comp-picker-group"><span>DOBRAS CUTÂNEAS</span>${skin.map(m=>bodyCompositionPickerCard(m,current)).join('')}</div></div></div>`;
