  function dataFoundationStatusLabel(audit=workspaceOwnershipAudit(state)){
    if(audit.foreign)return 'Revisão necessária';
    if(state.dataFoundation?.ownershipMode!=='workspace-bound'||audit.missing)return 'Preparação pendente';
    if(!state.dataFoundation?.postMigrationBackupAt)return 'Protegida • falta backup final';
    return 'Protegida';
  }

  function dataFoundationStatusTone(audit=workspaceOwnershipAudit(state)){
    if(audit.foreign)return 'danger';
    if(state.dataFoundation?.ownershipMode!=='workspace-bound'||audit.missing||!state.dataFoundation?.postMigrationBackupAt)return 'warn';
    return 'good';
  }

  function openDataFoundationCenter(){
    state.dataFoundation=normalizeDataFoundation(state.dataFoundation,state.workspace?.id,stateHasBusinessData(state));
    const audit=workspaceOwnershipAudit(state),bound=state.dataFoundation.ownershipMode==='workspace-bound'&&!audit.missing&&!audit.foreign,pre=Boolean(state.dataFoundation.preMigrationBackupAt),post=Boolean(state.dataFoundation.postMigrationBackupAt),tone=dataFoundationStatusTone(audit);
    const groups=audit.groups.map(g=>`<div><span>${escapeHTML(g.key)}</span><strong>${g.owned}/${g.total}</strong><small>${g.missing?`${g.missing} sem vínculo`:g.foreign?`${g.foreign} divergente(s)`:'OK'}</small></div>`).join('');
    openModal('Proteção dos dados do Studio',`<div class="license-center-hero ${tone==='good'?'good':tone==='danger'?'danger':'warn'}"><span>${tone==='good'?'✓':tone==='danger'?'×':'!'}</span><div><small>SEPARAÇÃO DOS DADOS</small><strong>${escapeHTML(dataFoundationStatusLabel(audit))}</strong><p>${audit.foreign?'Encontramos registros que precisam ser revisados antes de continuar.':bound?'Os registros deste Studio estão organizados e protegidos.':'O app pode organizar os registros deste Studio sem alterar valores, agenda ou avaliações.'}</p></div></div><div class="account-center-section"><div class="section-overline">1 • CÓPIA DE SEGURANÇA</div><div class="settings-row"><div><strong>${pre?'Cópia criada':'Crie uma cópia antes de continuar'}</strong><span>${pre?formatDateTimeBR(state.dataFoundation.preMigrationBackupAt):'É uma proteção extra antes de organizar os dados.'}</span></div><button class="btn ${pre?'btn-secondary':'btn-primary'} btn-small" id="foundationBackupBefore">${pre?'Refazer':'Fazer backup'}</button></div></div><div class="account-center-section"><div class="section-overline">2 • ORGANIZAR DADOS</div><div class="notice compact ${audit.foreign?'danger':''}">${audit.foreign?`Há ${audit.foreign} registro(s) que parecem pertencer a outra conta. A organização automática foi bloqueada para evitar mistura de dados.`:bound?'Tudo certo: os dados deste Studio já estão organizados.':'Esta ação apenas organiza a identificação dos registros. Nenhum aluno, valor, histórico, agenda ou avaliação será alterado.'}</div><button class="btn ${bound?'btn-secondary':'btn-primary'}" id="foundationMigrate" ${(!pre||audit.foreign||bound)?'disabled':''}>${bound?'Dados organizados':'Organizar agora'}</button></div><div class="account-center-section"><div class="section-overline">3 • NOVA CÓPIA</div><div class="settings-row"><div><strong>${post?'Cópia final criada':'Finalize com um novo backup'}</strong><span>${post?formatDateTimeBR(state.dataFoundation.postMigrationBackupAt):'Guarde uma nova cópia depois da organização.'}</span></div><button class="btn ${post?'btn-secondary':'btn-primary'} btn-small" id="foundationBackupAfter" ${bound?'':'disabled'}>${post?'Refazer':'Fazer backup'}</button></div></div><details class="settings-simple-details"><summary><span>Informações técnicas para suporte</span><b aria-hidden="true">⌄</b></summary><div class="settings-simple-details-body"><div class="license-center-grid"><div><span>Conta do Studio</span><strong>${escapeHTML(workspaceShortId())}</strong></div><div><span>Cobertura</span><strong>${audit.coverage}%</strong></div><div><span>Sem vínculo</span><strong>${audit.missing}</strong></div><div><span>Divergentes</span><strong>${audit.foreign}</strong></div></div>${groups?`<div class="license-center-grid">${groups}</div>`:''}</div></details><div class="modal-actions"><button type="button" class="btn btn-primary" data-close-modal>Concluir</button></div>`);
    $('#foundationBackupBefore')?.addEventListener('click',()=>exportBackup('pre-migration'));
    $('#foundationBackupAfter')?.addEventListener('click',()=>exportBackup('post-migration'));
    $('#foundationMigrate')?.addEventListener('click',()=>{
      const current=workspaceOwnershipAudit(state);if(!state.dataFoundation?.preMigrationBackupAt)return toast('Faça a cópia de segurança primeiro.');if(current.foreign)return toast('Organização bloqueada: há registros que precisam ser revisados.');
      const result=bindRecordsToWorkspace(state),after=workspaceOwnershipAudit(state),now=new Date().toISOString();
      state.dataFoundation={...normalizeDataFoundation(state.dataFoundation,state.workspace.id,stateHasBusinessData(state)),ownershipMode:'workspace-bound',migratedAt:state.dataFoundation.migratedAt||now,lastCheckedAt:now,lastStatus:after.foreign?'danger':after.missing?'pending':'ok',lastSummary:{total:after.total,owned:after.owned,missing:after.missing,foreign:after.foreign,boundNow:result.bound}};
      addAudit('Proteção dos dados consolidada',`${result.bound} registro(s) organizados • ${after.total} verificados`);saveState();closeModal();renderSettings();setTimeout(openDataFoundationCenter,80);toast('Dados do Studio organizados com segurança.');
    });
  }

  function approxStateBytes(source=state){
    try{return new Blob([JSON.stringify(source)]).size}catch{return 0}
  }

  function formatBytes(bytes=0){
    const n=Math.max(0,Number(bytes)||0);
    if(n<1024)return `${n} B`;
    if(n<1024*1024)return `${(n/1024).toFixed(n<10240?1:0)} KB`;
    return `${(n/1024/1024).toFixed(2)} MB`;
  }

  function duplicateIds(rows=[]){
    const seen=new Set(),dup=new Set();
    (Array.isArray(rows)?rows:[]).forEach(row=>{const id=String(row?.id||'').trim();if(!id)return;if(seen.has(id))dup.add(id);else seen.add(id)});
    return [...dup];
  }

  function backupAgeDays(){
    const raw=state.settings?.lastBackupAt;if(!raw)return null;
    const d=new Date(raw);if(Number.isNaN(d.getTime()))return null;
    return Math.max(0,Math.floor((Date.now()-d.getTime())/86400000));
  }

  function runCommercialIntegrityCheck(){
    const checks=[];
    const push=(id,label,status,detail)=>checks.push({id,label,status,detail});
    const workspaceOk=Boolean(state.workspace?.id&&state.workspace?.createdAt);
    push('workspace','Workspace do Studio',workspaceOk?'ok':'danger',workspaceOk?`Identidade ${workspaceShortId()} ativa.`:'Identidade lógica ausente. Faça backup antes de qualquer alteração.');
    push('schema','Esquema de dados',Number(state.version)===DATA_SCHEMA_VERSION?'ok':'danger',`Estado V${Number(state.version)||'—'} • esperado V${DATA_SCHEMA_VERSION}.`);
    const commercialOk=Number(state.commercial?.schemaVersion)===COMMERCIAL_SCHEMA_VERSION&&Number(state.commercial?.license?.schemaVersion)===COMMERCIAL_LICENSE_SCHEMA_VERSION&&Number(state.commercial?.onboarding?.schemaVersion)===COMMERCIAL_ONBOARDING_SCHEMA_VERSION&&Number(state.commercial?.privacy?.schemaVersion)===COMMERCIAL_PRIVACY_SCHEMA_VERSION&&Number(state.commercial?.infrastructure?.schemaVersion)===COMMERCIAL_INFRASTRUCTURE_SCHEMA_VERSION&&Boolean(state.commercial?.installation?.id);
    push('commercial','Conta e instalação',commercialOk?'ok':'danger',commercialOk?`Estrutura V${COMMERCIAL_SCHEMA_VERSION} • instalação ${installationShortId()} • proprietário ${commercialOwnerConfigured()?'configurado':'ainda não informado'}.`:'Estrutura comercial ou identidade desta instalação ausente.');
    const ownership=workspaceOwnershipAudit(state),foundationBound=state.dataFoundation?.ownershipMode==='workspace-bound';
    const ownershipStatus=ownership.foreign?'danger':(!foundationBound||ownership.missing)?'warn':'ok';
    push('ownership','Vínculo dos dados ao Workspace',ownershipStatus,ownership.foreign?`${ownership.foreign} registro(s) pertencem a outro Workspace. Migração automática bloqueada.`:(!foundationBound||ownership.missing)?`${ownership.owned}/${ownership.total} registros vinculados • ${ownership.missing} pendente(s). Use Fundação comercial dos dados.`:`${ownership.total} registro(s) protegidos pelo Workspace ${workspaceShortId()}.`);
    const profile=commercialStudioProfile(),profileOk=Boolean(profile.studioName&&profile.professionalName);
    push('profile','Perfil do Studio',profileOk?'ok':'warn',profileOk?`${profile.studioName} • identidade documental preparada.`:'Complete nome do Studio e profissional responsável em Conta e plano.');
    const license=commercialLicense(),licenseOk=Boolean(license&&license.plan&&license.status&&license.source);
    push('license','Plano e licença',licenseOk?'ok':'danger',licenseOk?(license.plan==='local'&&license.source==='local'?`Plano Local ativo • licença online não vinculada • sem cobrança.`:`Plano ${commercialPlanLabel()} • ${commercialLicenseStatusLabel()} • origem ${license.source}.`):'Estrutura de licença ausente ou inválida.');
    const infrastructure=commercialInfrastructure(),infraReady=infrastructure.backendFoundationVersion>=COMMERCIAL_BACKEND_FOUNDATION_VERSION&&infrastructure.status==='connected';
    push('commercial-backend','Fundação SaaS online',infraReady?'ok':studentPortalBackendConfigured()?'warn':'warn',infraReady?`Backend comercial V${infrastructure.backendFoundationVersion} verificado e ligado ao Workspace.`:studentPortalBackendConfigured()?'Backend do Portal configurado; fundação comercial ainda não verificada.':'Backend online ainda não configurado nesta instalação.');
    const privacy=commercialPrivacy(),privacyReady=Number(privacy.legalBackendVersion)>=1&&privacy.documentsPublished&&Boolean(privacy.termsVersion&&privacy.privacyVersion&&privacy.termsAcceptedAt&&privacy.privacyAcceptedAt);
    push('privacy','Privacidade e direitos de dados',privacyReady?'ok':'warn',privacyReady?`Governança jurídica pronta • Termos ${privacy.termsVersion} • Privacidade ${privacy.privacyVersion} • aceite vigente.`:'Portabilidade pronta; governança jurídica exige backend V1, publicação versionada e aceite atual.');
    const access=commercialAccess(),accessMembers=Array.isArray(access.members)?access.members:[],ownerCount=accessMembers.filter(x=>x.id==='owner'&&x.role==='owner'&&x.status==='active').length,activeAccess=accessMembers.filter(x=>x.status!=='inactive'),credentialsOk=access.mode!=='local-session'||activeAccess.every(accessCredentialReady),recoveryOk=access.mode!=='local-session'||Boolean(access.recoverySalt&&access.recoveryHash),accessOk=Number(access.schemaVersion)===ACCESS_SCHEMA_VERSION&&ownerCount===1&&credentialsOk&&recoveryOk;
    push('access','Equipe e permissões',accessOk?'ok':'danger',accessOk?`${accessMembers.length} ${accessMembers.length===1?'perfil local':'perfis locais'} • ${activeAccess.length} ativo(s) • matriz V${ACCESS_SCHEMA_VERSION} • ${access.mode==='local-session'?'sessões por perfil ativas':'sessões por perfil desativadas'}.`:'Estrutura de acesso inválida, credencial pendente ou proprietário principal ausente.');
    const portal=normalizeStudentPortal(state.studentPortal),portalOk=Number(portal.schemaVersion)===STUDENT_PORTAL_SCHEMA_VERSION&&portal.students&&typeof portal.students==='object';
    const portalBackend=studentPortalBackendStatus();
    push('student-portal','Portal do Aluno',portalOk?'ok':'danger',portalOk?`Fundação V${STUDENT_PORTAL_SCHEMA_VERSION} • cliente remoto isolado • backend ${portalBackend.connected?'conectado com RLS':portalBackend.configured?'configurado, aguardando vínculo':'não configurado'}.`:'Estrutura do Portal do Aluno inválida.');
    const arrays=['students','payments','receipts','expenses','physicalAssessments','posturalAssessments','auditLog','trash'];
    const objects=['schedule','attendance','makeups','settings'];
    const invalid=[...arrays.filter(k=>!Array.isArray(state[k])),...objects.filter(k=>!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))];
    push('structure','Estrutura principal',invalid.length?'danger':'ok',invalid.length?`Campos inválidos: ${invalid.join(', ')}.`:'Coleções essenciais estão no formato esperado.');
    const duplicateGroups=[['alunos',duplicateIds(state.students)],['receitas',duplicateIds(state.payments)],['recibos',duplicateIds(state.receipts)],['gastos',duplicateIds(state.expenses)],['avaliações físicas',duplicateIds(state.physicalAssessments)],['avaliações posturais',duplicateIds(state.posturalAssessments)]].filter(([,ids])=>ids.length);
    push('ids','Identificadores únicos',duplicateGroups.length?'danger':'ok',duplicateGroups.length?`Duplicidades detectadas em ${duplicateGroups.map(([name,ids])=>`${name} (${ids.length})`).join(', ')}.`:'Nenhuma duplicidade crítica de ID encontrada.');
    const op=state.settings?.operationConfig,mods=Array.isArray(op?.modalities)?op.modalities:[];
    const modDup=duplicateIds(mods);
    push('agenda','Configuração da Agenda',(!op||!mods.length||modDup.length)?'danger':'ok',!op?'Configuração operacional ausente.':!mods.length?'Nenhuma modalidade configurada.':modDup.length?`${modDup.length} modalidade(s) com ID duplicado.`:`${activeScheduleDays().length} dia(s) ativo(s) • ${mods.filter(x=>x.enabled).length} modalidade(s) habilitada(s).`);
    const bytes=approxStateBytes();
    const storageStatus=bytes>=4.5*1024*1024?'danger':bytes>=3.5*1024*1024?'warn':'ok';
    push('storage','Tamanho local',storageStatus,`${formatBytes(bytes)} utilizados pelo estado principal${storageStatus==='warn'?' • atenção ao crescimento de imagens e histórico.':storageStatus==='danger'?' • próximo do limite comum de armazenamento local.':''}`);
    const age=backupAgeDays();
    const backupStatus=age===null?'warn':age>30?'danger':age>7?'warn':'ok';
    push('backup','Backup recente',backupStatus,age===null?'Nenhum backup registrado neste aparelho.':age===0?'Backup realizado hoje.':`Último backup há ${age} dia(s) • V${state.settings?.lastBackupVersion||'—'}.`);
    const swSupported='serviceWorker' in navigator,swControlled=Boolean(navigator.serviceWorker?.controller);
    push('pwa','Camada de atualização',!swSupported?'warn':swControlled?'ok':'warn',!swSupported?'Service Worker não suportado neste navegador.':swControlled?'Service Worker ativo e controlando esta instalação.':'Service Worker disponível, mas ainda sem controle desta sessão.');
    const cryptoOk=Boolean(globalThis.crypto?.subtle&&globalThis.crypto?.getRandomValues&&globalThis.TextEncoder&&globalThis.TextDecoder);
    push('crypto','Validação criptográfica de backup',cryptoOk?'ok':'warn',cryptoOk?'SHA-256 e Web Crypto disponíveis para novos backups.':'Web Crypto indisponível neste ambiente; backups locais continuam compatíveis, mas o cofre protegido ficará indisponível.');
    push('cloud-vault','Cofre de backup protegido',cryptoOk?'ok':'warn',cryptoOk?`AES-256-GCM • PBKDF2-HMAC-SHA-256 (${CLOUD_BACKUP_PBKDF2_ITERATIONS.toLocaleString('pt-BR')} iterações) • senha não armazenada.`:'Criptografia autenticada indisponível neste navegador.');
    const danger=checks.filter(x=>x.status==='danger').length,warn=checks.filter(x=>x.status==='warn').length;
    const status=danger?'danger':warn?'warn':'ok';
    return {checks,status,danger,warn,bytes,summaryLabel:danger?'Ação necessária':warn?'Atenção':'Tudo certo'};
  }

  function supportReportText(result=runCommercialIntegrityCheck()){
    const counts=backupSummaryFor(state),standalone=window.matchMedia?.('(display-mode: standalone)')?.matches||navigator.standalone===true;
    const lines=[
      'MB Gestor Luxury Pro — Relatório de suporte',
      `Gerado em: ${new Date().toLocaleString('pt-BR')}`,
      `Versão do app: ${APP_VERSION}`,
      `Esquema de dados: ${DATA_SCHEMA_VERSION}`,
      `Workspace: ${workspaceShortId()}`,
      `Modo: ${state.workspace?.mode||'local'}`,
      `Base comercial: V${state.commercial?.schemaVersion||'—'} • conta ${state.commercial?.accountMode||'local'} • plano ${state.commercial?.license?.plan||'local'} • licença ${state.commercial?.license?.status||'—'}`,
      `Fundação SaaS: V${commercialInfrastructure().backendFoundationVersion||0}/${COMMERCIAL_BACKEND_FOUNDATION_VERSION} • ${commercialInfrastructure().status} • Workspace ${state.workspace?.mode||'local'}` ,
      `Instalação: ${installationShortId()} • proprietário configurado ${commercialOwnerConfigured()?'sim':'não'} • código de suporte ${supportAccessCode()}`,
      `Equipe e permissões: V${commercialAccess().schemaVersion||'—'} • ${commercialAccess().members.length} perfil(is) local(is) • ${commercialAccess().members.filter(x=>x.status!=='inactive').length} ativo(s) • modo ${commercialAccess().mode||'local-prepared'}`,
      `Fundação de dados: V${state.dataFoundation?.schemaVersion||'—'} • modo ${state.dataFoundation?.ownershipMode||'—'} • cobertura ${workspaceOwnershipAudit(state).coverage}%`,
      `Execução: ${standalone?'PWA instalada':'navegador'} • online ${navigator.onLine===false?'não':'sim'}`,
      `Armazenamento do estado: ${formatBytes(result.bytes)}`,
      `Último backup: ${state.settings?.lastBackupAt?formatDateTimeBR(state.settings.lastBackupAt):'não registrado'} • versão ${state.settings?.lastBackupVersion||'—'}`,
      `Cofre protegido: ${state.settings?.protectedBackup?.lastCreatedAt?`última cópia ${formatDateTimeBR(state.settings.protectedBackup.lastCreatedAt)}`:'ainda não utilizado'} • formato ${CLOUD_BACKUP_FORMAT_VERSION}`,
      `Portal do Aluno: fundação V${STUDENT_PORTAL_SCHEMA_VERSION} • backend ${studentPortalBackendStatus().connected?'conectado com RLS':studentPortalBackendStatus().configured?'configurado':'não configurado'} • publicados ${studentPortalStats().published}`,
      '',
      'CONTAGENS (sem nomes, telefones ou valores)',
      `Alunos: ${counts.students}`,
      `Receitas: ${counts.payments}`,
      `Recibos: ${counts.receipts||0}`,
      `Gastos: ${counts.expenses}`,
      `Registros de aula: ${counts.attendanceRecords}`,
      `Avaliações físicas: ${(state.physicalAssessments||[]).length}`,
      `Avaliações posturais: ${(state.posturalAssessments||[]).length}`,
      '',
      `DIAGNÓSTICO: ${result.summaryLabel} • ${result.danger} crítico(s) • ${result.warn} atenção(ões)`,
      ...result.checks.map(c=>`[${c.status.toUpperCase()}] ${c.label}: ${c.detail}`),
      '',
      'Privacidade: este relatório não inclui nomes de alunos, dados do proprietário, contatos, valores financeiros, fotos, logotipos ou conteúdo clínico/avaliativo.'
    ];
    return lines.join('\n');
  }

  function downloadText(name,text){
    // V12.5.1 • BOM UTF-8 + CRLF: evita mojibake em visualizadores de texto do Android/Samsung.
    const utf8Text=`\uFEFF${String(text??'').replace(/\r?\n/g,'\r\n')}`;
    const blob=new Blob([utf8Text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');
    a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200);
  }

  function openCommercialDiagnostics(){
    const result=runCommercialIntegrityCheck();
    const iconFor=status=>status==='ok'?'✓':status==='warn'?'!':'×';
    const simpleText=result.status==='ok'?'Nenhum problema encontrado.':result.status==='warn'?'Há alguns pontos que vale revisar.':'Encontramos um ponto que precisa de atenção.';
    openModal('Verificação do app',`<div class="diagnostic-hero ${result.status}"><span>${iconFor(result.status)}</span><div><strong>${escapeHTML(result.summaryLabel)}</strong><small>${escapeHTML(simpleText)}</small></div></div><div class="notice compact">Esta verificação apenas confere o app. Nenhum dado é alterado.</div><details class="settings-simple-details" ${result.status==='ok'?'':'open'}><summary><span>Ver detalhes da verificação</span><b aria-hidden="true">⌄</b></summary><div class="settings-simple-details-body"><div class="diagnostic-list">${result.checks.map(c=>`<div class="diagnostic-row ${c.status}"><b>${iconFor(c.status)}</b><div><strong>${escapeHTML(c.label)}</strong><span>${escapeHTML(c.detail)}</span></div></div>`).join('')}</div></div></details><div class="modal-actions diagnostic-actions"><button class="btn btn-secondary" data-close-modal>Fechar</button><button class="btn btn-secondary" id="copySupportReport">Copiar para suporte</button><button class="btn btn-primary" id="downloadSupportReport">Baixar arquivo</button></div>`);
    const report=supportReportText(result);
    $('#downloadSupportReport')?.addEventListener('click',()=>{downloadText(`MB_Gestor_Diagnostico_V${APP_VERSION.replaceAll('.','_')}_${isoToday()}.txt`,report);addAudit('Relatório de suporte gerado',`V${APP_VERSION} • ${result.summaryLabel}`);saveState();toast('Arquivo para suporte gerado sem dados pessoais.');});
    $('#copySupportReport')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(report);toast('Informações copiadas para suporte.')}catch{toast('Não foi possível copiar automaticamente. Use “Baixar arquivo”.')}});
  }

  async function sha256Hex(text=''){
    try{
      if(!globalThis.crypto?.subtle||!globalThis.TextEncoder)return '';
      const data=new TextEncoder().encode(String(text)),hash=await crypto.subtle.digest('SHA-256',data);
      return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');
    }catch{return ''}
  }

